// Plain-language metric guidance. See README for the authoritative specification.
static METRICS:&[Metric]=&[
Metric { key:"AV",name:"Attack vector",question:"Where can the attacker reach the vulnerable component?",group:0,options:&[OptionDef {value:"N",label:"Network",explanation:"The component can be attacked remotely across a network, potentially over the internet."},OptionDef {value:"A",label:"Adjacent",explanation:"The attacker must share a restricted network context, such as the same local subnet or Bluetooth range."},OptionDef {value:"L",label:"Local",explanation:"The attacker needs local access or must cause a user to interact with a locally delivered payload."},OptionDef {value:"P",label:"Physical",explanation:"The attacker must physically touch or manipulate the vulnerable system."},]},
Metric { key:"AC",name:"Attack complexity",question:"Must the attacker overcome a security measure?",group:0,options:&[OptionDef {value:"L",label:"Low",explanation:"No special action is needed to evade or overcome a security mechanism."},OptionDef {value:"H",label:"High",explanation:"The attacker must evade or overcome a security mechanism, such as address randomization or obtaining a target-specific secret."},]},
Metric { key:"AT",name:"Attack requirements",question:"Does success depend on a particular deployment or execution condition?",group:0,options:&[OptionDef {value:"N",label:"None",explanation:"No particular deployment or execution condition is required for exploitation."},OptionDef {value:"P",label:"Present",explanation:"Success depends on conditions outside the attacker’s control, such as a race or an on-path position."},]},
Metric { key:"PR",name:"Privileges required",question:"What access must the attacker already have?",group:0,options:&[OptionDef {value:"N",label:"None",explanation:"No authenticated privileges are needed before the attack."},OptionDef {value:"L",label:"Low",explanation:"The attacker needs basic user privileges, usually limited to their own settings or resources."},OptionDef {value:"H",label:"High",explanation:"The attacker needs significant administrative or equivalent control before exploitation."},]},
Metric { key:"UI",name:"User interaction",question:"What must someone other than the attacker do?",group:0,options:&[OptionDef {value:"N",label:"None",explanation:"The attack succeeds without another person taking action."},OptionDef {value:"P",label:"Passive",explanation:"A person interacts normally with the system, such as viewing a page or receiving content; no deliberate bypass is needed."},OptionDef {value:"A",label:"Active",explanation:"A person must take a specific conscious action, such as importing a file or overriding a warning."},]},
Metric { key:"VC",name:"Confidentiality · vulnerable system",question:"Can the attacker read protected information? Assess the vulnerable system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"All information can be exposed, or the exposed information has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some restricted information is exposed, but the attacker has limited control over what is revealed."},OptionDef {value:"N",label:"None",explanation:"There is no confidentiality impact on the vulnerable system."},]},
Metric { key:"VI",name:"Integrity · vulnerable system",question:"Can the attacker change protected information? Assess the vulnerable system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"The attacker can change any information, or the modification has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some information can be changed, but the scope or consequences are limited."},OptionDef {value:"N",label:"None",explanation:"There is no integrity impact on the vulnerable system."},]},
Metric { key:"VA",name:"Availability · vulnerable system",question:"Can the attacker interrupt access to the system? Assess the vulnerable system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"Access can be fully denied, or the disruption has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Performance or access is reduced, but the system remains at least partially available."},OptionDef {value:"N",label:"None",explanation:"There is no availability impact on the vulnerable system."},]},
Metric { key:"SC",name:"Confidentiality · subsequent system",question:"Can the attacker read protected information? Assess the subsequent system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"All information can be exposed, or the exposed information has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some restricted information is exposed, but the attacker has limited control over what is revealed."},OptionDef {value:"N",label:"None",explanation:"There is no confidentiality impact on the subsequent system."},]},
Metric { key:"SI",name:"Integrity · subsequent system",question:"Can the attacker change protected information? Assess the subsequent system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"The attacker can change any information, or the modification has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some information can be changed, but the scope or consequences are limited."},OptionDef {value:"N",label:"None",explanation:"There is no integrity impact on the subsequent system."},]},
Metric { key:"SA",name:"Availability · subsequent system",question:"Can the attacker interrupt access to the system? Assess the subsequent system.",group:0,options:&[OptionDef {value:"H",label:"High",explanation:"Access can be fully denied, or the disruption has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Performance or access is reduced, but the system remains at least partially available."},OptionDef {value:"N",label:"None",explanation:"There is no availability impact on the subsequent system."},]},
Metric { key:"E",name:"Exploit maturity",question:"What evidence of exploitation exists?",group:1,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No threat assessment is supplied. Scoring assumes the most severe value: Attacked."},OptionDef {value:"A",label:"Attacked",explanation:"Attacks have been reported, or usable tools exist that simplify exploitation."},OptionDef {value:"P",label:"Proof of concept",explanation:"A proof of concept is available, but attacks have not been reported and practical exploitation tools are not known."},OptionDef {value:"U",label:"Unreported",explanation:"No public proof of concept or attacks are known after considering available intelligence."},]},
Metric { key:"CR",name:"Confidentiality requirement",question:"How important is this security property in your environment?",group:2,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No local requirement is supplied. Scoring assumes High."},OptionDef {value:"H",label:"High",explanation:"Losing this property would have a catastrophic adverse effect on the organization or people."},OptionDef {value:"M",label:"Medium",explanation:"Losing this property would have a serious adverse effect."},OptionDef {value:"L",label:"Low",explanation:"Losing this property would have a limited adverse effect."},]},
Metric { key:"IR",name:"Integrity requirement",question:"How important is this security property in your environment?",group:2,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No local requirement is supplied. Scoring assumes High."},OptionDef {value:"H",label:"High",explanation:"Losing this property would have a catastrophic adverse effect on the organization or people."},OptionDef {value:"M",label:"Medium",explanation:"Losing this property would have a serious adverse effect."},OptionDef {value:"L",label:"Low",explanation:"Losing this property would have a limited adverse effect."},]},
Metric { key:"AR",name:"Availability requirement",question:"How important is this security property in your environment?",group:2,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No local requirement is supplied. Scoring assumes High."},OptionDef {value:"H",label:"High",explanation:"Losing this property would have a catastrophic adverse effect on the organization or people."},OptionDef {value:"M",label:"Medium",explanation:"Losing this property would have a serious adverse effect."},OptionDef {value:"L",label:"Low",explanation:"Losing this property would have a limited adverse effect."},]},
Metric { key:"MAV",name:"Modified attack vector",question:"Assess this metric for your deployment. Where can the attacker reach the vulnerable component?",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"N",label:"Network",explanation:"The component can be attacked remotely across a network, potentially over the internet."},OptionDef {value:"A",label:"Adjacent",explanation:"The attacker must share a restricted network context, such as the same local subnet or Bluetooth range."},OptionDef {value:"L",label:"Local",explanation:"The attacker needs local access or must cause a user to interact with a locally delivered payload."},OptionDef {value:"P",label:"Physical",explanation:"The attacker must physically touch or manipulate the vulnerable system."},]},
Metric { key:"MAC",name:"Modified attack complexity",question:"Assess this metric for your deployment. Must the attacker overcome a security measure?",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"L",label:"Low",explanation:"No special action is needed to evade or overcome a security mechanism."},OptionDef {value:"H",label:"High",explanation:"The attacker must evade or overcome a security mechanism, such as address randomization or obtaining a target-specific secret."},]},
Metric { key:"MAT",name:"Modified attack requirements",question:"Assess this metric for your deployment. Does success depend on a particular deployment or execution condition?",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"N",label:"None",explanation:"No particular deployment or execution condition is required for exploitation."},OptionDef {value:"P",label:"Present",explanation:"Success depends on conditions outside the attacker’s control, such as a race or an on-path position."},]},
Metric { key:"MPR",name:"Modified privileges required",question:"Assess this metric for your deployment. What access must the attacker already have?",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"N",label:"None",explanation:"No authenticated privileges are needed before the attack."},OptionDef {value:"L",label:"Low",explanation:"The attacker needs basic user privileges, usually limited to their own settings or resources."},OptionDef {value:"H",label:"High",explanation:"The attacker needs significant administrative or equivalent control before exploitation."},]},
Metric { key:"MUI",name:"Modified user interaction",question:"Assess this metric for your deployment. What must someone other than the attacker do?",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"N",label:"None",explanation:"The attack succeeds without another person taking action."},OptionDef {value:"P",label:"Passive",explanation:"A person interacts normally with the system, such as viewing a page or receiving content; no deliberate bypass is needed."},OptionDef {value:"A",label:"Active",explanation:"A person must take a specific conscious action, such as importing a file or overriding a warning."},]},
Metric { key:"MVC",name:"Modified confidentiality · vulnerable system",question:"Assess this metric for your deployment. Can the attacker read protected information? Assess the vulnerable system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"All information can be exposed, or the exposed information has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some restricted information is exposed, but the attacker has limited control over what is revealed."},OptionDef {value:"N",label:"None",explanation:"There is no confidentiality impact on the vulnerable system."},]},
Metric { key:"MVI",name:"Modified integrity · vulnerable system",question:"Assess this metric for your deployment. Can the attacker change protected information? Assess the vulnerable system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"The attacker can change any information, or the modification has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some information can be changed, but the scope or consequences are limited."},OptionDef {value:"N",label:"None",explanation:"There is no integrity impact on the vulnerable system."},]},
Metric { key:"MVA",name:"Modified availability · vulnerable system",question:"Assess this metric for your deployment. Can the attacker interrupt access to the system? Assess the vulnerable system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"Access can be fully denied, or the disruption has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Performance or access is reduced, but the system remains at least partially available."},OptionDef {value:"N",label:"None",explanation:"There is no availability impact on the vulnerable system."},]},
Metric { key:"MSC",name:"Modified confidentiality · subsequent system",question:"Assess this metric for your deployment. Can the attacker read protected information? Assess the subsequent system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"All information can be exposed, or the exposed information has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some restricted information is exposed, but the attacker has limited control over what is revealed."},OptionDef {value:"N",label:"None",explanation:"There is no confidentiality impact on the subsequent system."},]},
Metric { key:"MSI",name:"Modified integrity · subsequent system",question:"Assess this metric for your deployment. Can the attacker change protected information? Assess the subsequent system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"The attacker can change any information, or the modification has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Some information can be changed, but the scope or consequences are limited."},OptionDef {value:"N",label:"None",explanation:"There is no integrity impact on the subsequent system."},OptionDef {value:"S",label:"Safety",explanation:"An impact on human safety is possible in this environment, including serious injury or worse."},]},
Metric { key:"MSA",name:"Modified availability · subsequent system",question:"Assess this metric for your deployment. Can the attacker interrupt access to the system? Assess the subsequent system.",group:2,options:&[OptionDef {value:"X",label:"Use base",explanation:"Use the corresponding Base metric. No environmental override is applied."},OptionDef {value:"H",label:"High",explanation:"Access can be fully denied, or the disruption has a direct, serious consequence."},OptionDef {value:"L",label:"Low",explanation:"Performance or access is reduced, but the system remains at least partially available."},OptionDef {value:"N",label:"None",explanation:"There is no availability impact on the subsequent system."},OptionDef {value:"S",label:"Safety",explanation:"An impact on human safety is possible in this environment, including serious injury or worse."},]},
Metric { key:"S",name:"Safety",question:"Could exploitation affect human safety?",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No safety assessment is supplied."},OptionDef {value:"N",label:"Negligible",explanation:"No material human safety consequence is expected."},OptionDef {value:"P",label:"Present",explanation:"Human safety consequences are possible. This supplemental value does not change the score."},]},
Metric { key:"AU",name:"Automatable",question:"Can an attacker automate the full attack chain?",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"Automation has not been assessed."},OptionDef {value:"N",label:"No",explanation:"The attacker cannot reliably automate reconnaissance, weaponization, delivery, and exploitation."},OptionDef {value:"Y",label:"Yes",explanation:"The full attack chain can be automated across multiple targets."},]},
Metric { key:"R",name:"Recovery",question:"How does the system recover after an attack?",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"Recovery has not been assessed."},OptionDef {value:"A",label:"Automatic",explanation:"The system recovers automatically without user or administrator intervention."},OptionDef {value:"U",label:"User",explanation:"A user or administrator must intervene to restore operation."},OptionDef {value:"I",label:"Irrecoverable",explanation:"Recovery is not possible through normal restoration; replacement or rebuilding is needed."},]},
Metric { key:"V",name:"Value density",question:"How concentrated is the value exposed by an attack?",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"Value concentration has not been assessed."},OptionDef {value:"D",label:"Diffuse",explanation:"The affected component holds relatively little value per successful attack."},OptionDef {value:"C",label:"Concentrated",explanation:"A single successful attack gives access to a significant concentration of resources or value."},]},
Metric { key:"RE",name:"Response effort",question:"How much effort does initial response require?",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"Response effort has not been assessed."},OptionDef {value:"L",label:"Low",explanation:"Initial response needs little effort or resources."},OptionDef {value:"M",label:"Moderate",explanation:"Initial response needs some substantial effort or resources."},OptionDef {value:"H",label:"High",explanation:"Initial response needs significant, extensive effort or resources."},]},
Metric { key:"U",name:"Provider urgency",question:"What urgency has the vulnerability provider communicated? These labels are provider-defined, not standardized deadlines or CVSS severity bands.",group:3,options:&[OptionDef {value:"X",label:"Not defined",explanation:"No provider urgency is supplied."},OptionDef {value:"Clear",label:"Clear",explanation:"The provider assigns the Clear urgency designation."},OptionDef {value:"Green",label:"Green",explanation:"The provider assigns the Green urgency designation."},OptionDef {value:"Amber",label:"Amber",explanation:"The provider assigns the Amber urgency designation."},OptionDef {value:"Red",label:"Red",explanation:"The provider assigns the Red urgency designation."},]},
];
